import * as zod from "zod";

export const withdrawalCurrencyMin = 3;
export const withdrawalCurrencyMax = 3;

export const withdrawalAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");
export const withdrawalFeeAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");
export const withdrawalRefundAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");
export const withdrawalDeductedAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");
export const withdrawalSettledAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");
export const withdrawalChargedFeeAmountRegExp = new RegExp("^[0-9]{1,15}([.][0-9]{1,10})?$");

export const Withdrawal = zod
  .strictObject({
    id: zod.uuid(),
    billing_account_id: zod.int(),
    currency: zod.string().min(withdrawalCurrencyMin).max(withdrawalCurrencyMax),
    amount: zod.string().regex(withdrawalAmountRegExp),
    fee_amount: zod.string().regex(withdrawalFeeAmountRegExp),
    refund_amount: zod.string().regex(withdrawalRefundAmountRegExp),
    deducted_amount: zod.string().regex(withdrawalDeductedAmountRegExp),
    settled_amount: zod.string().regex(withdrawalSettledAmountRegExp),
    charged_fee_amount: zod.string().regex(withdrawalChargedFeeAmountRegExp),
    status: zod.enum([
      "pending",
      "processing",
      "succeeded",
      "partially_completed",
      "failed",
      "reversed",
    ]),
    created_at: zod.iso.datetime({ offset: true }),
    completed_at: zod.iso.datetime({ offset: true }).optional(),
    created_by: zod
      .string()
      .optional()
      .describe(
        "Identity that submitted this withdrawal. It can differ from the billing account owner.",
      ),
  })
  .describe(
    "An account withdrawal to the original payment methods of its unused top-ups. Accepted amounts are fixed. deducted_amount, settled_amount and charged_fee_amount report completed source items. Failed items release their principal and fee reservations; successful items are retained when another source fails.",
  );

export type Withdrawal = zod.input<typeof Withdrawal>;
export type WithdrawalOutput = zod.output<typeof Withdrawal>;
